window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dc1dd1b14706c717"]={"versions": [{"id": "FIG-dc1dd1b14706c717", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur AUTOSAR-ECU-Konfiguration (ECUC) der RTE-Spezifikation (AUTOSAR_SWS_RTE). Das Diagramm modelliert die strukturelle Definition des Konfigurationscontainers für die Interaktion zwischen der RTE und dem Betriebssystem (OS) über <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>RteOsInteraction : EcucParamConfContainerDef</code> mit der Multiplizität <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind drei Kind-Container eingebunden:</p>\n<ul class=\"fig-list\">\n<li><code>RteUsedOsActivation : EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteModeToScheduleTableMapping : EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteSyncPoint : EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ablauf- oder Verhaltenssemantik. Die Instanziierung erfolgt im Rahmen des Konfigurationsprozesses der RTE vor der Codegenerierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterdefinition der RTE. <code>RteOsInteraction</code> muss mindestens einmal konfiguriert werden (<code>1..<em></code>). Die untergeordneten Container für OS-Aktivierungen (<code>RteUsedOsActivation</code>), Modus-zu-Schedule-Table-Mappings (<code>RteModeToScheduleTableMapping</code>) und Synchronisationspunkte (<code>RteSyncPoint</code>) sind optional (<code>0..</em></code>). Konfigurationswerkzeuge und Codegeneratoren müssen diese Struktur und Multiplizitäten validieren.</p>"}, {"id": "FIG-99269bb07d84d6cf", "releases": ["R18-10_R4.4.0_R1.5.0", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur AUTOSAR-ECU-Konfiguration (ECUC) der RTE-Spezifikation (AUTOSAR_SWS_RTE). Das Diagramm modelliert die strukturelle Definition des Konfigurationscontainers für die Interaktion zwischen der RTE und dem Betriebssystem (OS) über <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>RteOsInteraction: EcucParamConfContainerDef</code> mit der Multiplizität <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind vier Kind-Container angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>RteUsedOsActivation: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteModeToScheduleTableMapping: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteSyncPoint: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteOsTaskChain: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ablauf- oder Verhaltenssemantik. Die Instanziierung erfolgt im Rahmen des Konfigurationsprozesses der RTE vor der Codegenerierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterdefinition der RTE. <code>RteOsInteraction</code> muss mindestens einmal konfiguriert werden (<code>1..<em></code>). Sämtliche Sub-Container für OS-Aktivierungen (<code>RteUsedOsActivation</code>), Modus-zu-Schedule-Table-Mappings (<code>RteModeToScheduleTableMapping</code>), Synchronisationspunkte (<code>RteSyncPoint</code>) sowie Task-Ketten (<code>RteOsTaskChain</code>) sind optional instanziierbar (<code>0..</em></code>). Konfigurations- und Codegenerierungswerkzeuge müssen die Unterstützung für <code>RteOsTaskChain</code> bereitstellen.</p>"}, {"id": "FIG-23ae5da46308aa72", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur AUTOSAR-ECU-Konfiguration (ECUC) der RTE-Spezifikation (AUTOSAR_SWS_RTE). Das Diagramm modelliert die strukturelle Definition des Konfigurationscontainers für die Interaktion zwischen der RTE und dem Betriebssystem (OS) über <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>RteOsInteraction: EcucParamConfContainerDef</code> mit der Multiplizität <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind vier Kind-Container angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>RteUsedOsActivation: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteModeToScheduleTableMapping: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteSyncPoint: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteOsTaskChain: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ablauf- oder Verhaltenssemantik. Die Instanziierung erfolgt im Rahmen des Konfigurationsprozesses der RTE vor der Codegenerierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterdefinition der RTE. <code>RteOsInteraction</code> muss mindestens einmal konfiguriert werden (<code>1..<em></code>). Sämtliche Sub-Container für OS-Aktivierungen (<code>RteUsedOsActivation</code>), Modus-zu-Schedule-Table-Mappings (<code>RteModeToScheduleTableMapping</code>), Synchronisationspunkte (<code>RteSyncPoint</code>) sowie Task-Ketten (<code>RteOsTaskChain</code>) sind optional instanziierbar (<code>0..</em></code>). Konfigurations- und Codegenerierungswerkzeuge müssen die Unterstützung für <code>RteOsTaskChain</code> bereitstellen.</p>"}, {"id": "FIG-f576bd1d18f22bc5", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur AUTOSAR-ECU-Konfiguration (ECUC) der RTE-Spezifikation (AUTOSAR_SWS_RTE). Das Diagramm modelliert die strukturelle Definition des Konfigurationscontainers für die Interaktion zwischen der RTE und dem Betriebssystem (OS) über <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>RteOsInteraction: EcucParamConfContainerDef</code> mit der Multiplizität <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind vier Kind-Container angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>RteUsedOsActivation: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteModeToScheduleTableMapping: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteSyncPoint: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteOsTaskChain: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ablauf- oder Verhaltenssemantik. Die Instanziierung erfolgt im Rahmen des Konfigurationsprozesses der RTE vor der Codegenerierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterdefinition der RTE. <code>RteOsInteraction</code> muss mindestens einmal konfiguriert werden (<code>1..<em></code>). Sämtliche Sub-Container für OS-Aktivierungen (<code>RteUsedOsActivation</code>), Modus-zu-Schedule-Table-Mappings (<code>RteModeToScheduleTableMapping</code>), Synchronisationspunkte (<code>RteSyncPoint</code>) sowie Task-Ketten (<code>RteOsTaskChain</code>) sind optional instanziierbar (<code>0..</em></code>). Konfigurations- und Codegenerierungswerkzeuge müssen die Unterstützung für <code>RteOsTaskChain</code> bereitstellen.</p>"}, {"id": "FIG-f64f761e270a4e3f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur AUTOSAR-ECU-Konfiguration (ECUC) der RTE-Spezifikation (AUTOSAR_SWS_RTE). Das Diagramm modelliert die strukturelle Definition des Konfigurationscontainers für die Interaktion zwischen der RTE und dem Betriebssystem (OS) über <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>RteOsInteraction: EcucParamConfContainerDef</code> mit der Multiplizität <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind vier Kind-Container angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>RteUsedOsActivation: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteModeToScheduleTableMapping: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteSyncPoint: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteOsTaskChain: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ablauf- oder Verhaltenssemantik. Die Instanziierung erfolgt im Rahmen des Konfigurationsprozesses der RTE vor der Codegenerierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterdefinition der RTE. <code>RteOsInteraction</code> muss mindestens einmal konfiguriert werden (<code>1..<em></code>). Sämtliche Sub-Container für OS-Aktivierungen (<code>RteUsedOsActivation</code>), Modus-zu-Schedule-Table-Mappings (<code>RteModeToScheduleTableMapping</code>), Synchronisationspunkte (<code>RteSyncPoint</code>) sowie Task-Ketten (<code>RteOsTaskChain</code>) sind optional instanziierbar (<code>0..</em></code>). Konfigurations- und Codegenerierungswerkzeuge müssen die Unterstützung für <code>RteOsTaskChain</code> bereitstellen.</p>"}, {"id": "FIG-d360f5e792155a3f", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur AUTOSAR-ECU-Konfiguration (ECUC) der RTE-Spezifikation (AUTOSAR_SWS_RTE). Das Diagramm modelliert die strukturelle Definition des Konfigurationscontainers für die Interaktion zwischen der RTE und dem Betriebssystem (OS) über <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>RteOsInteraction: EcucParamConfContainerDef</code> mit der Multiplizität <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</p>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind vier Kind-Container angebunden:</p>\n<ul class=\"fig-list\">\n<li><code>RteUsedOsActivation: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteModeToScheduleTableMapping: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteSyncPoint: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n<li><code>RteOsTaskChain: EcucParamConfContainerDef</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ablauf- oder Verhaltenssemantik. Die Instanziierung erfolgt im Rahmen des Konfigurationsprozesses der RTE vor der Codegenerierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterdefinition der RTE. Die Definition des Containers <code>RteOsInteraction</code> ist optional und auf maximal eine Instanz beschränkt (<code>0..1</code>). Die Sub-Container <code>RteUsedOsActivation</code>, <code>RteModeToScheduleTableMapping</code>, <code>RteSyncPoint</code> und <code>RteOsTaskChain</code> sind jeweils optional und beliebig oft instanziierbar (<code>0..*</code>), sofern der übergeordnete Container vorhanden ist. Konfigurations- und Validierungswerkzeuge müssen sicherstellen, dass maximal eine Instanz von <code>RteOsInteraction</code> konfiguriert wird.</p>"}], "trans": [{"from": "FIG-dc1dd1b14706c717", "to": "FIG-99269bb07d84d6cf", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung des Sub-Containers <code>RteOsTaskChain: EcucParamConfContainerDef</code> mit Kompositionsbeziehung <code>+subContainer</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.</li>\n<li>Redaktionelle Anpassung der Header-Formatierung (Entfernung von Leerzeichen vor dem Doppelpunkt, z. B. <code>RteOsInteraction:</code> statt <code>RteOsInteraction :</code>).</li>\n</ul>"}, {"from": "FIG-99269bb07d84d6cf", "to": "FIG-23ae5da46308aa72", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-23ae5da46308aa72", "to": "FIG-99269bb07d84d6cf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-99269bb07d84d6cf", "to": "FIG-f576bd1d18f22bc5", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f576bd1d18f22bc5", "to": "FIG-f64f761e270a4e3f", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f64f761e270a4e3f", "to": "FIG-d360f5e792155a3f", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Änderung der Multiplizität von <code>RteOsInteraction: EcucParamConfContainerDef</code>: <code>lowerMultiplicity</code> von <code>1</code> auf <code>0</code> und <code>upperMultiplicity</code> von <code>*</code> auf <code>1</code> geändert.</li>\n</ul>"}]};
